

# This file was *autogenerated* from the file /Users/masaori/git/masaori/math/.claude/worktrees/reflective-fluttering-panda/exact-solution-of-2d-ising-model/sagemath/check/193_claim_recover_Z_Y_from_hatZ_hatY/check_01_inverse_transform.sage
from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_1 = Integer(1); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_0p0 = RealNumber('0.0')# recover_Z_Y_from_hatZ_hatY: 逆変換
#   sum_{mu=1}^{M} hatY_mu exp(i m 2 pi mu / M) = M Y_m
#   sum_{mu=1}^{M} hatZ^{(-)}_mu exp(i m 2 pi mu / M) = M Z_m
#   ゆえに Y_m = (1/M) sum ...,  Z_m = (1/M) sum ...
#
# 独立経路:
#   左辺: hatZ_op / hatY_op（Fourier 側）を mu について足し上げる
#   右辺: Zop / Yop（実空間側）を直接構成する
# 両者は別の作り方なので、一致は非自明である。
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

rep = CheckReport("recover_Z_Y_from_hatZ_hatY: hat から Z, Y の復元")

M_LIST = [_sage_const_2 , _sage_const_3 , _sage_const_4 , _sage_const_5 ]

for M in M_LIST:
    Mi = int(M)
    for m in range(_sage_const_1 , Mi + _sage_const_1 ):
        sY = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
        sZ = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
        for mu in range(_sage_const_1 , Mi + _sage_const_1 ):
            ph = _np.exp(_sage_const_1j  * float(m) * _sage_const_2  * _np.pi * float(mu) / float(Mi))
            sY = sY + hatY_op(mu, M) * ph
            sZ = sZ + hatZ_op(mu, M, '-') * ph
        rep.close(sY, float(Mi) * Yop(m, M), "M=%d m=%d: Σ_μ hatY_μ e^{imθ_μ} = M Y_m" % (M, m))
        rep.close(sZ, float(Mi) * Zop(m, M), "M=%d m=%d: Σ_μ hatZ^{(-)}_μ e^{imθ_μ} = M Z_m" % (M, m))
        rep.close(sY / float(Mi), Yop(m, M), "M=%d m=%d: Y_m = (1/M) Σ_μ ..." % (M, m))
        rep.close(sZ / float(Mi), Zop(m, M), "M=%d m=%d: Z_m = (1/M) Σ_μ ..." % (M, m))

    # 証明が使う直交性 (∗): Σ_{mu=1}^{M} exp((m-j) 2πiμ/M) = M (j=m), 0 (j≠m)
    for m in range(_sage_const_1 , Mi + _sage_const_1 ):
        for j in range(_sage_const_1 , Mi + _sage_const_1 ):
            s = sum(_np.exp(_sage_const_1j  * float(m - j) * _sage_const_2  * _np.pi * float(mu) / float(Mi))
                    for mu in range(_sage_const_1 , Mi + _sage_const_1 ))
            rep.close(s, float(Mi) if j == m else _sage_const_0p0 ,
                      "M=%d m=%d j=%d: 直交性 (∗)" % (M, m, j))

    # hatZ^{(-)} の重みが全 j で +1 であること（statement の前置き）
    for mu in [_sage_const_1 , -_sage_const_1 , Mi, -Mi]:
        naive = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
        for j in range(_sage_const_1 , Mi + _sage_const_1 ):
            naive = naive + Zop(j, M) * _np.exp(-_sage_const_1j  * float(j) * _sage_const_2  * _np.pi * float(mu) / float(Mi))
        rep.close(hatZ_op(mu, M, '-'), naive,
                  "M=%d mu=%+d: hatZ^{(-)} は全 j で重み +1" % (M, mu))

rep.finish()

